import { Outlet, NavLink } from 'react-router-dom'

function Layout() {
  return (
    <>
      <header>
        <nav>
          <NavLink to="/">Home</NavLink> |{' '}
          <NavLink to="/products">Products</NavLink> |{' '}
          <NavLink to="/orders">Orders</NavLink>
        </nav>
      </header>

      <main>
        <Outlet />
      </main>
    </>
  )
}

export default Layout
